d.selection.select(function () { var o = [], i; for (i = 0; i < 48; i++) o.push([705 + 190 * Math.cos(i * Math.PI / 24), 230 + 230 * Math.sin(i * Math.PI / 24)]); return o; }());
d.selection.feather(60); d.selection.fill(hexc('#FFFFFF'), ColorBlendMode.NORMAL, 20, false);
