function ell(cx, cy, rx, ry) { var o = [], i; for (i = 0; i < 64; i++) o.push([cx + rx * Math.cos(i * Math.PI / 32), cy + ry * Math.sin(i * Math.PI / 32)]); return o; }
function box(x0, y0, x1, y1) { return [[x0, y0], [x1, y0], [x1, y1], [x0, y1]]; }
